# vse.S -- directed test: the unit-stride stores vse<eew>.v (unmasked) at VLEN 128, a doubleword at a
# time through the scalar LSU, each writing its active bytes alone (docs/PLAN-2026-11-25-vector.md
# §8). Generated by the session's vse_gen.py; src byte j is (7j + 1) mod 256, the destination is
# 160 bytes of 0xee before each test and is compared whole against the expected image after.
#
#   1  VS Off: vse8.v is an illegal instruction
#   2  e8, m1, vl 16, an aligned destination
#   3  e32, m1, vl 4, 4 past a doubleword
#   4  e8, m1, vl 5, 3 past one: the bytes past vl are not written
#   5  e16, m2, vl 13, 6 past one: both registers
#   6  e64, m8, vl 16: all eight registers
#   7  a fractional EMUL: vse8.v at e64, m1 (EMUL 1/8), vl 2
#   8  an EMUL above 8 is illegal, as is any at vill
#   9  vl 0 at address 0 (no memory there): nothing is written, nothing faults
#  10  vstart 3: the prestart bytes are not written, and vstart reads 0 after
#  11  S-mode, Sv39: e8, vl 6 ending at an unmapped page: no fault
#  12  ...and vl 16 takes a store page fault at element 6 (tval the page, vstart 6) with bytes 0..5
#      stored; the handler maps the page, the retry stores the rest
#
# A trap is counted in s5 (mcause in s3, mtval in s4); with s6 nonzero the handler records vstart in
# s9 and the doubleword before the page in s8, writes s6 to the PTE at s7 and retries, else returns
# past the instruction. An ecall from S ends the run with the verdict in a0.
#   tohost = 1 PASS, else FAIL with test# = tohost>>1

	.option	arch, +v
#define VSTART 0x008

	.section .text.init,"ax",@progbits
	.globl _start
_start:
	la	t0, trap_handler
	csrw	mtvec, t0
	li	s5, 0
	li	s6, 0
	csrw	mstatus, x0

	#---------------- 1: VS Off
	la	a2, dst
	vse8.v	v1, (a2)
	li	t2, 1
	bne	s5, t2, fail1
	li	t0, 1 << 9		# VS Initial
	csrw	mstatus, t0
	li	s5, 0
	# the sources: v1 = src[0..15], v4..v5 = src[0..31], v8..v15 = src[0..127]
	la	a2, src
	vl1re8.v	v1, (a2)
	vl2re8.v	v4, (a2)
	vl8re8.v	v8, (a2)

	#---------------- 2
	call	filld
	vsetivli	t0, 16, e8, m1, ta, ma
	la	a2, dst
	vse8.v	v1, (a2)
	la	a2, dst
	la	a5, exp2
	call	cmpd
	bnez	a0, fail2
	#---------------- 3
	call	filld
	vsetivli	t0, 4, e32, m1, ta, ma
	la	a2, dst
	addi	a2, a2, 4
	vse32.v	v1, (a2)
	la	a2, dst
	la	a5, exp3
	call	cmpd
	bnez	a0, fail3
	#---------------- 4
	call	filld
	vsetivli	t0, 5, e8, m1, ta, ma
	la	a2, dst
	addi	a2, a2, 3
	vse8.v	v1, (a2)
	la	a2, dst
	la	a5, exp4
	call	cmpd
	bnez	a0, fail4
	#---------------- 5
	call	filld
	vsetivli	t0, 13, e16, m2, ta, ma
	la	a2, dst
	addi	a2, a2, 6
	vse16.v	v4, (a2)
	la	a2, dst
	la	a5, exp5
	call	cmpd
	bnez	a0, fail5
	#---------------- 6
	call	filld
	vsetivli	t0, 16, e64, m8, ta, ma
	la	a2, dst
	addi	a2, a2, 8
	vse64.v	v8, (a2)
	la	a2, dst
	la	a5, exp6
	call	cmpd
	bnez	a0, fail6
	#---------------- 7
	call	filld
	vsetivli	t0, 2, e64, m1, ta, ma
	la	a2, dst
	addi	a2, a2, 1
	vse8.v	v1, (a2)
	la	a2, dst
	la	a5, exp7
	call	cmpd
	bnez	a0, fail7
	#---------------- 8: illegal EMUL, vill
	vsetivli	t0, 16, e8, m8, ta, ma
	la	a2, dst
	vse64.v	v16, (a2)
	li	t2, 1
	bne	s5, t2, fail8
	li	a1, 0x100
	li	a0, 4
	vsetvl	t0, a0, a1
	vse8.v	v1, (a2)
	li	t2, 2
	bne	s5, t2, fail8
	li	s5, 0
	#---------------- 9: vl 0 at address 0
	call	filld
	vsetivli	t0, 0, e8, m1, ta, ma
	li	a2, 0
	vse8.v	v1, (a2)
	bnez	s5, fail9
	la	a2, dst
	la	a5, exp9
	call	cmpd
	bnez	a0, fail9
	#---------------- 10: vstart 3
	call	filld
	vsetivli	t0, 16, e8, m1, ta, ma
	li	t0, 3
	csrw	VSTART, t0
	la	a2, dst
	vse8.v	v1, (a2)
	csrr	t1, VSTART
	bnez	t1, fail10
	bnez	s5, fail10
	la	a2, dst
	la	a5, exp10
	call	cmpd
	bnez	a0, fail10
	#---------------- 11, 12: S-mode, page faults
	la	t0, pt2
	la	t1, pt1
	srli	t1, t1, 12
	slli	t1, t1, 10
	ori	t1, t1, 1
	sd	t1, 8(t0)
	li	t1, (0x80000 << 10) | 0xcf
	sd	t1, 16(t0)
	la	t0, pt1
	la	t1, pt0
	srli	t1, t1, 12
	slli	t1, t1, 10
	ori	t1, t1, 1
	sd	t1, 0(t0)
	la	t0, pt0
	la	t1, pagea
	srli	t1, t1, 12
	slli	t1, t1, 10
	ori	t1, t1, 0xc7
	sd	t1, 0(t0)
	la	t0, pt2
	srli	t0, t0, 12
	li	t1, 8 << 60
	or	t0, t0, t1
	csrw	satp, t0
	sfence.vma
	li	t0, 3 << 11
	csrc	mstatus, t0
	li	t0, 1 << 11
	csrs	mstatus, t0
	la	t0, s_start
	csrw	mepc, t0
	mret

s_start:
	# 0xee over pagea's last doubleword and pageb's first two (through the gigapage)
	li	t0, 0xeeeeeeeeeeeeeeee
	lla	a4, pagea + 0xff8
	sd	t0, 0(a4)
	la	a4, pageb
	sd	t0, 0(a4)
	sd	t0, 8(a4)
	# 11: vl 6 ends at the page
	vsetivli	t0, 6, e8, m1, ta, ma
	li	a4, 0x40000ffa
	vse8.v	v1, (a4)
	bnez	s5, fail11
	lla	a4, pagea + 0xff8
	ld	t1, 0(a4)
	li	t2, 0x241d160f0801eeee
	bne	t1, t2, fail11
	li	t0, 0xeeeeeeeeeeeeeeee
	sd	t0, 0(a4)
	# 12: vl 16 faults at element 6
	la	s7, pt0
	addi	s7, s7, 8
	la	s6, pageb
	srli	s6, s6, 12
	slli	s6, s6, 10
	ori	s6, s6, 0xc7
	vsetivli	t0, 16, e8, m1, ta, ma
	li	a4, 0x40000ffa
	vse8.v	v1, (a4)
	li	t1, 1
	bne	s5, t1, fail12
	li	t1, 15
	bne	s3, t1, fail12
	li	t1, 0x40001000
	bne	s4, t1, fail12
	li	t1, 6
	bne	s9, t1, fail12
	li	t1, 0x241d160f0801eeee
	bne	s8, t1, fail12
	la	a4, pageb
	ld	t1, 0(a4)
	li	t2, 0x5c554e474039322b
	bne	t1, t2, fail12
	ld	t1, 8(a4)
	li	t2, 0xeeeeeeeeeeee6a63
	bne	t1, t2, fail12
	li	a0, 1
	ecall
fail1:	li	a0, 3
	j	done_m
fail2:	li	a0, 5
	j	done_m
fail3:	li	a0, 7
	j	done_m
fail4:	li	a0, 9
	j	done_m
fail5:	li	a0, 11
	j	done_m
fail6:	li	a0, 13
	j	done_m
fail7:	li	a0, 15
	j	done_m
fail8:	li	a0, 17
	j	done_m
fail9:	li	a0, 19
	j	done_m
fail10:	li	a0, 21
	j	done_m
fail11:	li	a0, 23
	ecall
fail12:	li	a0, 25
	ecall

	# dst := 0xee
filld:	la	t4, dst
	li	t5, 0xeeeeeeeeeeeeeeee
	li	t6, 20
1:	sd	t5, 0(t4)
	addi	t4, t4, 8
	addi	t6, t6, -1
	bnez	t6, 1b
	ret
	# a0 = 0 when the 20 doublewords at a2 equal those at a5
cmpd:	li	a0, 0
	li	t6, 20
1:	ld	t4, 0(a2)
	ld	t5, 0(a5)
	beq	t4, t5, 2f
	li	a0, 1
2:	addi	a2, a2, 8
	addi	a5, a5, 8
	addi	t6, t6, -1
	bnez	t6, 1b
	ret

	.align 2
trap_handler:
	csrr	s3, mcause
	csrr	s4, mtval
	li	t6, 9			# environment call from S
	beq	s3, t6, done_m
	addi	s5, s5, 1
	beqz	s6, 1f
	csrr	s9, VSTART
	lla	t6, pagea + 0xff8
	ld	s8, 0(t6)
	sd	s6, 0(s7)
	sfence.vma
	li	s6, 0
	mret
1:	csrr	t6, mepc
	addi	t6, t6, 4
	csrw	mepc, t6
	mret
done_m:
	la	t0, tohost
	sd	a0, 0(t0)
9:	j	9b

	.section .tohost,"aw",@progbits
	.align 6
	.globl tohost
tohost:	.dword 0
	.globl fromhost
fromhost:
	.dword 0

	.section .data
	.align 12
pt2:	.zero 4096
pt1:	.zero 4096
pt0:	.zero 4096
pagea:	.zero 4096
pageb:	.zero 4096
	.align 4
dst:	.zero 160
src:
